test("bulk reassign scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-05");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33", "from": "2026-03-01"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  expect(await ui.hold(pg_uma, p_ben, {"from": "2026-02-10"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  expect(await ui.retire(pg_uma, p_ada, "2026-03-15")).toBe(true);
  expect(await ui.hold(pg_uma, p_ben, {"from": "2026-02-10"})).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.hold(pg_uma, p_ada, {"from": "2026-03-01", "to": "2026-03-20"})).toBe(true);
  await ui.refresh(pg_uma);
  await ui.setSetting(pg_uma, "clerk-limit", "");
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.hold(pg_uma, p_ada, {"from": "2026-02-25", "to": "2026-03-09"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "A"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(false);
  expect(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00", "date": "2026-03-28"})).toBeNull();
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "0.04", "date": "2026-03-05", "note": "n"}));
  await ui.refresh(pg_uma);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "0.04", "date": "2026-02-10", "ref": " r-1 "}));
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  await ui.showRetired(pg_vic, true);
  expect(await ui.reassign(pg_vic, c_ada_0, "Ben")).toBe(true);
  expect(await ui.statementAsOf(pg_vic, p_ada, "2026-03-05")).toBe(false);

